stepxmp.pre:
figure {
    display: block;
    float: inline-start;
    width: 120pt;
    margin-inline-end: 8pt;
}

section > title {
    display: block;
    clear: both;
}

figure {
    display: block;
    float-reference: page;
    float: top;
    margin-block-end: 10pt;
}

article { column-count: 2; }
article figure {
    display: block;
    float-reference: column;
    float: bottom;
}

figure.wide {
    float-reference: page;
    float: top;
    float-defer: 1;
}

figure {
    display: block;
    float-reference: column;
    float: snap-block(2.5em);
}

figure.corner {
    float: left;
    width: 120pt;
    height: 120pt;
    shape-outside: polygon(0 0, 100% 0, 0 100%);
    shape-margin: 6pt;
}
